///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (scwin.gExmptYn === 'Y') {
            // bypass 일경우 뷰어 상태는 'A'여야 함 'A'는 사후심사
            scwin.gViewerStat = 'A';
        } else {
            scwin.gViewerStat = 'P';
        }
        if (colid === "DOC_TITLE") {

            fn_OpenNoDisclViewer(scwin.gAcptNo, scwin.gViewerStat, js_emp_no, js_dep_cd, js_jobtitl, js_duty, js_duty_chrg, 'P', dts_DutyStatus); // 2013.05.14
            // fn_OpenNoDisclViewer(gAcptNo, gViewerStat);
        } else if (colid === "ACPT_DDTM") {

            fn_OpenDisclAllList();
        } else if (colid === "COM_ABBRV") {

            fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N026_ex.grd_Grid_OnDblClick" });
    }
};

