};

/**
 * @method
 * @name cmb_TeamList_OnSelChange
 * @description cmb_TeamList 선택 변경 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_OnSelChange = function() {
    try {
        scwin.gDepCd = cmb_TeamList.ValueOfIndex("VALUE", cmb_TeamList.Index);
        if (scwin.gDepCd === '') {

            setObjectValue(cmb_EmpList, '');
        }

        dts_emp.UseFilter = true;

        dts_emp.Filter();
        dts_emp.SortExpr = "DEP_CD";
        dts_emp.Sort();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N026_ex.cmb_TeamList_OnSelChange" });
    }
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {

            if (dts_emp.NameValue(row, "dep_cd") === scwin.gDepCd ||

                dts_emp.NameValue(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N026_ex.dts_emp_OnFilter" });
    }
};

/**
