    }
};

/**
 * @method
 * @name dts_DsclStudyList_OnLoadCompleted
 * @description dts_DsclStudyList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DsclStudyList_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_DsclStudyList.errorMsg) {
            alert(dts_DsclStudyList.errorMsg);
        } else {

            FillGridHeaderTotalCnt(rowcount, panel_page);
        }
        // grd_Grid.Redraw ="true";
        /*
        var fFrame = frame.Provider("../").ActiveFrame.FrameID;
        var fname = frame.FrameID;
        if (fFrame == fname) {

        	CloseWin(rowcount, grd_Grid);
        }*/

        CloseWin(rowcount, grd_Grid);
        scwin.search_yn = false;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N026_ex.dts_DsclStudyList_OnLoadCompleted" });
    }
};

/**
         * @method
